<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['request_id','product_id']);db()->beginTransaction();try{$s=db()->prepare('SELECT * FROM product_requests WHERE id=? FOR UPDATE');$s->execute([$d['request_id']]);$r=$s->fetch();if(!$r||$r['status']!=='open')fail('Request is no longer open',409);if($r['requester_id']==$u['id'])fail('You cannot accept your own request');$s=db()->prepare("SELECT * FROM products WHERE id=? AND user_id=? AND status='available' FOR UPDATE");$s->execute([$d['product_id'],$u['id']]);$p=$s->fetch();if(!$p)fail('Choose one of your available products',403);$price=$d['agreed_price']??$p['selling_price'];db()->prepare('UPDATE products SET user_id=?,status="available" WHERE id=?')->execute([$r['requester_id'],$p['id']]);db()->prepare('UPDATE product_requests SET status="completed",accepted_by=?,accepted_product_id=?,agreed_price=? WHERE id=?')->execute([$u['id'],$p['id'],$price,$r['id']]);db()->prepare('INSERT INTO product_transfers(product_id,from_user_id,to_user_id,request_id,transfer_price,notes) VALUES(?,?,?,?,?,?)')->execute([$p['id'],$u['id'],$r['requester_id'],$r['id'],$price,$d['notes']??null]);db()->commit();out(['success'=>true,'message'=>'Ownership transferred successfully']);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();fail($e->getMessage(),400);}
